package edu.ankara.audiometer.application;
import edu.ankara.audiometer.domain.algorithm.*;import edu.ankara.audiometer.domain.config.*;import edu.ankara.audiometer.domain.model.*;import edu.ankara.audiometer.domain.fp.Result;import edu.ankara.audiometer.infrastructure.serial.*;import java.util.*;import java.util.function.Consumer;
public final class TestSessionService { private TestState state; private final SerialPortGateway gateway; private final List<Consumer<TestState>> listeners=new ArrayList<>(); public TestSessionService(AudiometryConfig c, SerialPortGateway g){state=TestState.initial(c); gateway=g;} public TestState state(){return state;} public void onState(Consumer<TestState> l){listeners.add(l);} private void set(TestState s){state=s; listeners.forEach(l->l.accept(s));} public void reset(){set(TestState.initial(state.config()));} public void setCriterion(ThresholdCriterion c){set(TestState.initial(state.config().withCriterion(c)));} public Result<Void,String> presentTone(){ TestState next=HughsonWestlakeEngine.presentTone(state); var cmd=SerialCommand.tone(next.presentations().getLast(), next.config()); if(cmd.isOk()) gateway.send(cmd.orElse(null).value()); set(next); return Result.ok(null);} public void response(){set(TestStateReducer.updateState(state,new ProtocolEvent.Response()));} public void noResponse(){set(TestStateReducer.updateState(state,new ProtocolEvent.NoResponse()));} public void applyRawMessages(List<String> raw){set(new SerialMessageProcessor(SerialProtocolConfig.defaults()).process(state,raw));} public SerialPortGateway gateway(){return gateway;} }
